import { BuiltinName } from "./builtin-name.ts";

// Single source of truth for the short, always-on feature-authoring guardrails.
//
// The same rules must reach three audiences that cannot share one delivery path:
//   1. the harness system prompt, injected at runtime by the agent runner;
//   2. the `AGENTS.md` scaffolded by `routekit-eval init`, read by external coding agents
//      that never boot through the RouteKitEval harness;
//   3. the `feature-development` skill markdown, read from the materialized skill.
// Audiences 1 and 2 import the renderers below directly, so they cannot drift.
// Audience 3 is Markdown and cannot import TypeScript, so its copy is generated
// from this module and a CI drift test keeps it fresh.

/** Title of the generated skill reference that mirrors these rules for agents. */
const FEATURE_AUTHORING_GUARDRAILS_TITLE = "Feature Authoring Guardrails";

/** Lead-in sentence shared by every rendering of the rule list. */
const FEATURE_AUTHORING_INTRO =
  "When creating or updating RouteKitEval features, skills, prompts, harnesses, routes, or other feature contributions:";

/**
 * The canonical guardrail sentences, in priority order. Each is self-contained so
 * it reads correctly as a numbered preamble item or a Markdown bullet. The lead-in
 * sentence above supplies the subject for the imperative "them".
 */
const FEATURE_AUTHORING_RULES: readonly string[] = [
  "Write them only under the active feature root.",
  "Use root skills at `<active-feature-root>/<feature-id>/SKILL.md`.",
  "Use nested skills at `<active-feature-root>/<feature-id>/skills/<skill-name>/SKILL.md` when a feature owns several related skills.",
  "Do not create project skills in `.agents/skills`, `.codex/skills`, a repository-level `skills/` directory, or anywhere outside the active feature root unless the user explicitly asks.",
  "If the owning feature is unclear, ask before creating files.",
  `For contribution shapes and authoring details, use the \`${BuiltinName.Skill}\` skill.`,
  "`.agents/skills` and `.claude/skills` are generated snapshot views of the active feature root; never edit them. Edits under the active feature root take effect on your next run, not mid-run.",
];

/** Render the rules as unwrapped Markdown bullets, e.g. for the scaffolded `AGENTS.md`. */
const formatFeatureAuthoringBullets = (): readonly string[] =>
  FEATURE_AUTHORING_RULES.map((rule) => `- ${rule}`);

// `oxfmt` is configured with `proseWrap: "never"`, so it collapses every prose
// block (paragraphs and list items alike) onto a single line and relies on soft
// wrapping in the editor/viewer. The generated reference file is the one surface
// that lives in this repo and is formatted, so emit each block unwrapped on a
// single line: the committed copy becomes a fixed point of `oxfmt` and the drift
// test never fights the formatter.
const renderMarkdownBlock = (text: string, prefix: string): string =>
  `${prefix}${text}`;

const GUARDRAILS_NOTICE =
  "Do not edit this file by hand. It is generated from `framework/contracts/internal/src/feature-authoring-rules.ts`, and the RouteKitEval runtime injects the same rules into the harness system prompt. This copy exists for agents reading the materialized skill.";

/**
 * The Markdown body of the generated `references/authoring-guardrails.md` skill
 * file, pre-wrapped to match `oxfmt` so the committed copy is byte-identical to
 * this output and the drift test stays green after formatting.
 */
export const formatFeatureAuthoringGuardrailsMarkdown = (): string =>
  `${[
    `# ${FEATURE_AUTHORING_GUARDRAILS_TITLE}`,
    "",
    renderMarkdownBlock(GUARDRAILS_NOTICE, ""),
    "",
    renderMarkdownBlock(FEATURE_AUTHORING_INTRO, ""),
    "",
    ...FEATURE_AUTHORING_RULES.map((rule) => renderMarkdownBlock(rule, "- ")),
  ].join("\n")}\n`;

export {
  FEATURE_AUTHORING_INTRO,
  FEATURE_AUTHORING_RULES,
  formatFeatureAuthoringBullets,
};
